begin;create extension if not exists pgtap with schema extensions;select plan(20);
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at)values('00000000-0000-0000-0000-000000000000','99900000-0000-4000-8000-000000000030','authenticated','authenticated','trial-owner@example.test','',now(),now(),now());
set local role authenticated;select set_config('request.jwt.claim.sub','99900000-0000-4000-8000-000000000030',true);select set_config('request.jwt.claims','{"sub":"99900000-0000-4000-8000-000000000030","role":"authenticated"}',true);
select public.create_business('trial-engine','Trial Engine Inc','Trial Engine','sole_proprietorship','retail','{"city":"Manila"}');
select set_config('test.trial_org',(select id::text from public.organizations where slug='trial-engine'),true);
select set_config('test.trial_version',(select version.id::text from public.business_os_template_versions version join public.business_os_templates template on template.id=version.template_id where template.key='retail-store-os'and version.status='published'order by version.version desc limit 1),true);
select is((public.get_business_trial_dashboard(current_setting('test.trial_org')::uuid)->>'trialStatus'),'not_started','A business without an activated OS has not started its trial');
select lives_ok($$select public.install_business_os_template(current_setting('test.trial_org')::uuid,current_setting('test.trial_version')::uuid)$$,'First Business OS activation starts the trial');
select results_eq($$select trial_status,trial_end_date-trial_start_date from public.business_trials where organization_id=current_setting('test.trial_org')::uuid$$,$$select'active'::text,interval'45 days'$$,'Trial window is exactly 45 days');
select results_eq($$select plan_key,status from public.subscriptions where organization_id=current_setting('test.trial_org')::uuid$$,$$select 'pro'::text,'trialing'::text$$,'Trial grants the full configured MVP entitlement');
select results_eq($$select milestone_key,status from public.business_trial_milestones where organization_id=current_setting('test.trial_org')::uuid and due_day=1$$,$$select 'day_1_os_created'::text,'achieved'::text$$,'Day 1 milestone is backed by the installation');
select results_eq($$select count(*)from public.business_trial_milestones where organization_id=current_setting('test.trial_org')::uuid$$,$$select 6::bigint$$,'All six milestones are created');
select lives_ok($$select public.install_business_os_template(current_setting('test.trial_org')::uuid,current_setting('test.trial_version')::uuid)$$,'Replaying template installation is safe');
select results_eq($$select count(*)from public.business_trials where organization_id=current_setting('test.trial_org')::uuid$$,$$select 1::bigint$$,'A business receives only one trial');
reset role;
insert into public.products(organization_id,product_type,name,default_unit,selling_price,cost_price,tax_type,tax_rate,status,created_by,updated_by)values(current_setting('test.trial_org')::uuid,'product','Trial Hammer','piece',250,150,'exclusive',12,'active','99900000-0000-4000-8000-000000000030','99900000-0000-4000-8000-000000000030');
insert into public.sales_customers(organization_id,branch_id,name)values(current_setting('test.trial_org')::uuid,(select id from public.branches where organization_id=current_setting('test.trial_org')::uuid order by created_at limit 1),'Trial Customer');
set local role authenticated;select set_config('request.jwt.claim.sub','99900000-0000-4000-8000-000000000030',true);select set_config('request.jwt.claims','{"sub":"99900000-0000-4000-8000-000000000030","role":"authenticated"}',true);
select is((public.get_business_trial_dashboard(current_setting('test.trial_org')::uuid)#>>'{metrics,productsCreated}'),'1','Product adoption comes from the catalog record');
select is((public.get_business_trial_dashboard(current_setting('test.trial_org')::uuid)#>>'{metrics,customersCreated}'),'1','Customer adoption comes from the CRM record');
select results_eq($$select status from public.business_trial_milestones where organization_id=current_setting('test.trial_org')::uuid and milestone_key='day_7_setup'$$,$$select 'achieved'::text$$,'Setup milestone is evidence-based');
select lives_ok($$select public.record_business_trial_adoption(current_setting('test.trial_org')::uuid,'report_viewed','trial-value-report','report-value-idempotent','{}')$$,'A report view can be recorded');
select lives_ok($$select public.record_business_trial_adoption(current_setting('test.trial_org')::uuid,'report_viewed','trial-value-report','report-value-idempotent','{}')$$,'An adoption event is idempotent');
select is((public.get_business_trial_dashboard(current_setting('test.trial_org')::uuid)#>>'{metrics,reportsViewed}'),'1','Duplicate report views do not inflate adoption');
select throws_ok($$insert into public.business_trial_adoption_events(organization_id,event_type,resource_key,idempotency_key,actor_id)values(current_setting('test.trial_org')::uuid,'report_viewed','bypass','bypass-event','99900000-0000-4000-8000-000000000030')$$,'42501','permission denied for table business_trial_adoption_events','Clients cannot bypass the adoption RPC');
reset role;update public.business_trials set trial_start_date=now()-interval'44 days',trial_end_date=now()+interval'1 day'where organization_id=current_setting('test.trial_org')::uuid;
set local role authenticated;select set_config('request.jwt.claim.sub','99900000-0000-4000-8000-000000000030',true);select set_config('request.jwt.claims','{"sub":"99900000-0000-4000-8000-000000000030","role":"authenticated"}',true);
select is((public.get_business_trial_dashboard(current_setting('test.trial_org')::uuid)->>'trialStatus'),'expiring','The final five days use the expiring status');
reset role;update public.business_trials set trial_start_date=now()-interval'46 days',trial_end_date=now()-interval'1 day'where organization_id=current_setting('test.trial_org')::uuid;
set local role authenticated;select set_config('request.jwt.claim.sub','99900000-0000-4000-8000-000000000030',true);select set_config('request.jwt.claims','{"sub":"99900000-0000-4000-8000-000000000030","role":"authenticated"}',true);
select is((public.get_business_trial_dashboard(current_setting('test.trial_org')::uuid)->>'trialStatus'),'expired','The lifecycle expires after day 45');
select results_eq($$select status from public.subscriptions where organization_id=current_setting('test.trial_org')::uuid$$,$$select 'paused'::text$$,'Expiration ends the trial entitlement without deleting records');
select lives_ok($$select public.convert_business_trial(current_setting('test.trial_org')::uuid)$$,'An authorized owner can convert an expired trial');
select results_eq($$select trial_status,converted_at is not null from public.business_trials where organization_id=current_setting('test.trial_org')::uuid$$,$$select 'converted'::text,true$$,'Conversion is permanent and timestamped');
select *from finish();rollback;
